def makegrid(h,w,bg,inside,rbs,cbs,marks):
    g=[[bg]*w for _ in range(h)]
    for r in range(h):
        if r not in rbs:
            for c in range(w):
                if c not in cbs:g[r][c]=inside
    for (r,c),v in marks.items():g[r][c]=v
    return g
